function jmLoginState(){var r=jmget(java,source,'/favorite?page=1&folder_id=0&o=mr');if(r==null){java.longToast('未登录或请求失败');return 'no';}var n=0;if(r.list!=null)n=r.list.length;if(r.folder_list!=null||r.count!=null){java.longToast('登录态有效，收藏夹 '+String(r.total||n)+' 本');return 'ok';}java.longToast('响应异常，可能未登录');return 'no';}
function jmDoLogin(){var info=null;try{info=source.getLoginInfoMap();}catch(e){info=null;}var uid='';var pwd='';try{if(info!=null){var a1=info.get('账号');if(a1!=null)uid=String(a1);var p1=info.get('密码');if(p1!=null)pwd=String(p1);if(uid.length<1){var u2=info.get('account');if(u2!=null)uid=String(u2);}if(pwd.length<1){var p2=info.get('password');if(p2!=null)pwd=String(p2);}}}catch(e){}
 if(uid.length<1||pwd.length<1){java.longToast('请先填写账号密码');return 'no';}
