    infomap = (infomap!="null"&&infomap!=""&&infomap!=null)?infomap:"{}";
    return JSON.parse(infomap);
}

function setHeaders(){
    const { source,java } = this;
    let map = getHeaderMap(this);
    for(let i=0;i<arguments.length;i++){
        let k =arguments[i].split("=")[0];
        let v =arguments[i].split("=")[1];
        map[k] = v;
    }
    source.putLoginHeader("#"+JSON.stringify(map))
}

function show(m,t){
    const {java,source} = this;
    this.setHeaders(t+"="+m);
    java.refreshExplore();
}

function isShow(m,z){
    const {source,java} = this;
    return (this.Map(m) == z || this.Map(m)=="")
}

function formatTimeDynamic(totalSeconds) {
  const hours = Math.floor(totalSeconds / 3600);
  const remainingSeconds = totalSeconds % 3600;
  const minutes = Math.floor(remainingSeconds / 60);
  const seconds = remainingSeconds % 60;

  const parts = [];

  if (hours > 0) {
    parts.push(hours.toString().padStart(2, '0'));
  }

  if (hours > 0) {
    parts.push(minutes.toString().padStart(2, '0'));
  } else {
    parts.push(minutes.toString());
  }

  parts.push(seconds.toString().padStart(2, '0'));

  return parts.join(':');
}

function formatCount(count) {
  if (count < 10000) return count.toString();  
  const inWan = (count / 10000).toFixed(2);
  return inWan.endsWith('.00') 
    ? `${inWan.split('.')[0]}万` 
    : `${inWan}万`;
}

