    var codeMatch = html.match(/<input type="hidden" name="code" value="([^"]+)"/);
    var hashMatch = html.match(/<input type="hidden" name="hash" value="([^"]+)"/);

    if (!codeMatch || !hashMatch) {
        // 如果提取失败，返回空（阅读APP会提示无结果）
        return "";
    }

    var code = codeMatch[1];
    var hash = hashMatch[1];

    // 构造搜索URL，关键词需要URL编码
    var url = searchPageUrl + "?s=" + encodeURIComponent(key) + "&code=" + code + "&hash=" + hash;
    return url;
})();

